pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner, address actor) public {
        vm.assume(actor != address(0) && _owner != address(0));
        // Setup: the original owner is this contract (the setUp deployer).
        // actor becomes the new owner by receiving ownership first.
        vm.prank(address(this));
        c.setOwner(actor);
        // Now actor is the current owner; call setOwner as actor.
        vm.prank(actor);
        bool success = c.setOwner(_owner);
        assertTrue(success);
    }
}

